def choose_move(observation):
    def clamp_step(v):
        if v > 0:
            return 1
        if v < 0:
            return -1
        return 0

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            x = v[0]
            y = v[1]
            if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                return x, y
        return default

    def step_toward(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return [clamp_step(bx - ax), clamp_step(by - ay)]

    def step_away(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return [clamp_step(ax - bx), clamp_step(ay - by)]

    def manhattan(a, b):
        ax, ay = pos(a)
        bx, by = pos(b)
        return abs(ax - bx) + abs(ay - by)

    def best_target(targets, here, prefer_farthest=False):
        if not targets:
            return None
        bh = pos(here)
        best = None
        best_score = None
        for t in targets:
            if not isinstance(t, (list, tuple)) or len(t) < 2:
                continue
            tt = pos(t)
            d = abs(tt[0] - bh[0]) + abs(tt[1] - bh[1])
            score = -d if prefer_farthest else d
            if best is None or score < best_score:
                best = tt
                best_score = score
        return best

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = best_target(corners, opp_pos, prefer_farthest=True)
        if target is None:
            target = (sx - (ox - sx), sy - (oy - sy))
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or []
        )
        target = best_target(targets, self_pos, prefer_farthest=False)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, opp_pos)

    resources = (
        observation.get("resources")
        or observation.get("resource_positions")
        or observation.get("resource_cells")
        or []
    )
    target = best_target(resources, self_pos, prefer_farthest=False)
    if target is not None:
        return step_toward(self_pos, target)

    # Fallbacks: chase opponent in denial modes, otherwise stay safe.
    if env == "resource_collection":
        return step_toward(self_pos, opp_pos)

    return [0, 0]

